import{_ as p,o as t,c as r,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const g=JSON.parse('{"title":"Ceph Day Germany - Ceph for Big Science","description":"","frontmatter":{"title":"Ceph Day Germany - Ceph for Big Science","date":"2018-02-14T00:00:00.000Z","updated":"2018-02-15T00:00:00.000Z","tags":["Ceph","大科学","分布式存储","高可用性","可扩展性"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2018/Ceph_Day_Germany_-_Ceph_for_Big_Science.md","filePath":"posts/2018/Ceph_Day_Germany_-_Ceph_for_Big_Science.md","lastUpdated":1780459816000}'),n={name:"posts/2018/Ceph_Day_Germany_-_Ceph_for_Big_Science.md"};function s(i,e,C,l,h,a){return t(),r("div",null,[...e[0]||(e[0]=[o('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间</strong>： 2023年11月（具体日期未提及）</p><p><strong>与会人员</strong>： CERN存储团队，Ceph社区开发者</p><p><strong>会议主题</strong>： CERN在Ceph存储上的使用经验及反馈</p><p><strong>会议内容</strong>：</p><p><strong>一、CERN存储架构概述</strong></p><ul><li>CERN拥有两个数据中心，分别位于瑞士和布达佩斯，使用Ceph存储系统进行数据存储，包括文件存储、块存储和对象存储。</li><li>当前运行着两个生产集群，其中最大的集群容量为5.5PB，另一个数据中心容量为0.5PB。</li><li>CERN使用Ceph进行物理实验数据存储、物理分析、S3存储和HPC模拟数据存储。</li></ul><p><strong>二、Ceph存储应用案例</strong></p><ul><li><strong>物理实验数据存储</strong>： 使用Ceph存储CMS、ALICE、ATLAS和LHCb等实验数据，每年存储约50PB数据。</li><li><strong>物理分析</strong>： 使用Ceph存储分析批处理目标数据，并使用Ceph作为虚拟化NFS文件系统。</li><li><strong>S3存储</strong>： 使用Ceph作为S3存储后端，提供S3服务。</li><li><strong>HPC</strong>： 使用Ceph存储HPC模拟数据，并使用Ceph作为NFS文件系统。</li></ul><p><strong>三、Ceph存储使用经验及反馈</strong></p><ul><li><strong>Ceph性能</strong>： Ceph在I/O吞吐量方面表现良好，但在元数据性能方面存在一些问题。</li><li><strong>Ceph稳定性</strong>： Ceph在Luminous版本中表现出良好的稳定性，但需要进一步优化。</li><li><strong>Ceph可扩展性</strong>： Ceph的可扩展性较好，但需要改进某些功能，例如替换OSD。</li><li><strong>Ceph管理</strong>： Ceph的管理较为复杂，需要进一步简化。</li><li><strong>Ceph工具</strong>： Ceph提供的工具需要改进，例如osdmap工具和scrub工具。</li></ul><p><strong>四、后续行动计划</strong></p><ul><li>与Ceph社区合作，改进Ceph的元数据性能和可扩展性。</li><li>开发Ceph管理工具，简化Ceph的管理。</li><li>开发Ceph存储的备份工具。</li><li>探索Ceph在更多场景下的应用。</li></ul><p><strong>五、会议总结</strong></p><p>CERN在Ceph存储上的使用经验表明，Ceph是一个功能强大且可扩展的存储系统，但在某些方面仍需改进。CERN将与Ceph社区合作，共同推动Ceph的发展。</p>',15)])])}const c=p(n,[["render",s]]);export{g as __pageData,c as default};
